package it.christian.qrwallet;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.*;import android.view.*;import android.widget.*;
import org.json.*;import java.io.*;import java.util.zip.*;

public class MainActivity extends Activity {
 static final int MIN=8,THUMB=101,CODE=102,EXPORT=201,IMPORT=202;
 SharedPreferences pref; LinearLayout root; EditText label; int selected=0;
 public void onCreate(Bundle b){super.onCreate(b);pref=getSharedPreferences("items",MODE_PRIVATE);if(!pref.contains("count"))pref.edit().putInt("count",MIN).apply();home();}
 int dp(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);} int count(){return Math.max(MIN,pref.getInt("count",MIN));} String get(String k,int i){return pref.getString(k+i,"");}
 TextView text(String s,int z,int c,int g){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setGravity(g);v.setPadding(dp(10),dp(8),dp(10),dp(8));return v;}
 GradientDrawable bg(int c,int stroke,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));if(stroke!=0)g.setStroke(dp(1),stroke);return g;}
 void shell(String title){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setBackgroundColor(Color.rgb(248,250,252));LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setBackgroundColor(Color.rgb(29,78,216));bar.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(dp(8),i.getSystemWindowInsetTop()+dp(16),dp(10),dp(10));return i;});Button menu=new Button(this);menu.setText("☰");menu.setTextSize(24);menu.setTextColor(Color.WHITE);menu.setBackgroundColor(Color.TRANSPARENT);menu.setOnClickListener(v->menu(menu));bar.addView(menu,new LinearLayout.LayoutParams(dp(58),dp(58)));TextView h=text(title,21,Color.WHITE,Gravity.CENTER_VERTICAL);h.setTypeface(Typeface.DEFAULT,Typeface.BOLD);bar.addView(h,new LinearLayout.LayoutParams(0,dp(58),1));root.addView(bar);setContentView(root);}
 void menu(View a){PopupMenu m=new PopupMenu(this,a);for(String s:new String[]{"HOME","GESTISCI CONTENUTI","ESPORTA","IMPORTA","INFORMAZIONI"})m.getMenu().add(s);m.setOnMenuItemClickListener(x->{saveLabel();String s=x.getTitle().toString();if(s.equals("HOME"))home();else if(s.startsWith("GESTISCI"))editor();else if(s.equals("ESPORTA"))exportStart();else if(s.equals("IMPORTA"))importHelp();else info();return true;});m.show();}
 void home(){label=null;shell("HOME");ScrollView sc=new ScrollView(this);LinearLayout all=new LinearLayout(this);all.setOrientation(LinearLayout.VERTICAL);GridLayout grid=new GridLayout(this);grid.setColumnCount(2);grid.setPadding(dp(8),dp(8),dp(8),dp(6));for(int i=0;i<count();i++){final int idx=i;LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.VERTICAL);card.setGravity(Gravity.CENTER);card.setPadding(dp(6),dp(5),dp(6),dp(5));card.setBackground(bg(Color.WHITE,Color.rgb(226,232,240),14));String t=get("t",i);if(!t.isEmpty()&&new File(t).exists()){ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.CENTER_CROP);im.setImageURI(Uri.fromFile(new File(t)));card.addView(im,new LinearLayout.LayoutParams(-1,dp(82)));}String n=get("n",i);TextView l=text(n.isEmpty()?"Elemento "+(i+1):n,16,Color.rgb(17,24,39),Gravity.CENTER);l.setTypeface(Typeface.DEFAULT,Typeface.BOLD);card.addView(l,new LinearLayout.LayoutParams(-1,dp(42)));card.setOnClickListener(v->open(idx));GridLayout.LayoutParams lp=new GridLayout.LayoutParams();lp.width=0;lp.height=dp(142);lp.columnSpec=GridLayout.spec(GridLayout.UNDEFINED,1f);lp.setMargins(dp(6),dp(6),dp(6),dp(6));grid.addView(card,lp);}all.addView(grid);Button plus=new Button(this);plus.setText("+");plus.setTextSize(30);plus.setTextColor(Color.WHITE);plus.setBackground(bg(Color.rgb(29,78,216),0,28));plus.setOnClickListener(v->{int n=count()+1;pref.edit().putInt("count",n).apply();selected=n-1;editor();});LinearLayout.LayoutParams pp=new LinearLayout.LayoutParams(-1,dp(58));pp.setMargins(dp(18),dp(6),dp(18),dp(22));all.addView(plus,pp);sc.addView(all);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
 void open(int i){String p=get("c",i);if(p.isEmpty()||!new File(p).exists()){Toast.makeText(this,"Nessun codice associato",Toast.LENGTH_SHORT).show();return;}shell(get("n",i).isEmpty()?"Codice":get("n",i));ImageView im=new ImageView(this);im.setScaleType(ImageView.ScaleType.FIT_CENTER);im.setImageURI(Uri.fromFile(new File(p)));im.setPadding(dp(18),dp(18),dp(18),dp(18));root.addView(im,new LinearLayout.LayoutParams(-1,0,1));Button back=new Button(this);back.setText("BACK");back.setTextSize(17);back.setTextColor(Color.WHITE);back.setBackground(bg(Color.rgb(29,78,216),0,12));back.setOnClickListener(v->home());LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,dp(58));bp.setMargins(dp(18),dp(10),dp(18),dp(20));root.addView(back,bp);}
 String item(int i){String n=get("n",i).trim();return(i+1)+": "+(n.isEmpty()?"vuoto":n);}String[] items(){String[]a=new String[count()];for(int i=0;i<a.length;i++)a[i]=item(i);return a;}
 void editor(){shell("GESTISCI CONTENUTI");ScrollView sc=new ScrollView(this);LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(18),dp(14),dp(18),dp(30));box.addView(text("Scegli un elemento, assegna un nome e seleziona le immagini. La miniatura è facoltativa.",15,Color.DKGRAY,Gravity.LEFT));Spinner sp=new Spinner(this);sp.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items()));sp.setSelection(Math.min(selected,count()-1));box.addView(sp,new LinearLayout.LayoutParams(-1,dp(56)));label=new EditText(this);label.setHint("Nome visualizzato");label.setText(get("n",selected));box.addView(label,new LinearLayout.LayoutParams(-1,dp(60)));LinearLayout checks=new LinearLayout(this);checks.setOrientation(LinearLayout.VERTICAL);box.addView(checks);Button th=new Button(this);th.setText("SELEZIONA MINIATURA (OPZIONALE)");box.addView(th,new LinearLayout.LayoutParams(-1,dp(58)));Button co=new Button(this);co.setText("SELEZIONA QR / CODICE A BARRE");box.addView(co,new LinearLayout.LayoutParams(-1,dp(58)));Button save=new Button(this);save.setText("SALVA");save.setTextColor(Color.WHITE);save.setBackground(bg(Color.rgb(29,78,216),0,12));box.addView(save,new LinearLayout.LayoutParams(-1,dp(58)));Runnable refresh=()->checks(checks);sp.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){boolean first=true;public void onNothingSelected(android.widget.AdapterView<?>a){}public void onItemSelected(android.widget.AdapterView<?>a,View v,int pos,long id){if(first){first=false;selected=pos;}else{saveLabel();selected=pos;label.setText(get("n",pos));}refresh.run();}});th.setOnClickListener(v->{saveLabel();pick(THUMB);});co.setOnClickListener(v->{saveLabel();pick(CODE);});save.setOnClickListener(v->{saveLabel();Toast.makeText(this,"Elemento salvato",Toast.LENGTH_SHORT).show();editor();});refresh.run();sc.addView(box);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));}
 void saveLabel(){if(label!=null)pref.edit().putString("n"+selected,label.getText().toString().trim()).apply();}void checks(LinearLayout b){b.removeAllViews();b.addView(check("Miniatura",get("t",selected)));b.addView(check("Codice",get("c",selected)));}TextView check(String n,String p){boolean ok=!p.isEmpty()&&new File(p).exists();TextView v=text(n+": "+(ok?"impostata  ✓":"non impostata"),16,ok?Color.rgb(22,163,74):Color.DKGRAY,Gravity.LEFT);if(ok)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 void pick(int r){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,r);}File image(int i,boolean t){File d=new File(getFilesDir(),"images");d.mkdirs();return new File(d,(t?"thumb_":"code_")+i+".img");}void copyAndClose(InputStream in,File f)throws IOException{try(InputStream src=in;OutputStream out=new FileOutputStream(f)){copyOpen(src,out);}}void copyOpen(InputStream in,OutputStream out)throws IOException{byte[]b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);}
 void exportStart(){saveLabel();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.setType("application/zip");i.putExtra(Intent.EXTRA_TITLE,"Q-Wallet-backup_1.5.zip");startActivityForResult(i,EXPORT);}void importHelp(){new AlertDialog.Builder(this).setTitle("Importa backup").setMessage("Seleziona direttamente il file ZIP creato dalla funzione Esporta. Non decomprimere il file.").setNegativeButton("ANNULLA",null).setPositiveButton("SELEZIONA ZIP",(d,w)->importStart()).show();}void importStart(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("application/zip");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}
 protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;try{Uri u=data.getData();if(r==THUMB||r==CODE){boolean t=r==THUMB;File f=image(selected,t);copyAndClose(getContentResolver().openInputStream(u),f);pref.edit().putString((t?"t":"c")+selected,f.getAbsolutePath()).apply();editor();}else if(r==EXPORT){exportZip(u);Toast.makeText(this,"Esportazione completata",Toast.LENGTH_LONG).show();}else if(r==IMPORT){importZip(u);Toast.makeText(this,"Importazione completata",Toast.LENGTH_LONG).show();home();}}catch(Exception e){Toast.makeText(this,"Errore: "+e.getMessage(),Toast.LENGTH_LONG).show();}}
 void exportZip(Uri u)throws Exception{JSONArray a=new JSONArray();try(ZipOutputStream z=new ZipOutputStream(getContentResolver().openOutputStream(u))){for(int i=0;i<count();i++){JSONObject o=new JSONObject();o.put("name",get("n",i));o.put("thumb",add(z,get("t",i),"images/thumb_"+i+".img"));o.put("code",add(z,get("c",i),"images/code_"+i+".img"));a.put(o);}JSONObject m=new JSONObject();m.put("app","Q Wallet");m.put("version","1.5");m.put("items",a);z.putNextEntry(new ZipEntry("manifest.json"));z.write(m.toString(2).getBytes("UTF-8"));z.closeEntry();}}
 String add(ZipOutputStream z,String p,String n)throws IOException{File f=new File(p);if(p.isEmpty()||!f.exists())return"";z.putNextEntry(new ZipEntry(n));try(InputStream in=new FileInputStream(f)){copyOpen(in,z);}z.closeEntry();return n;}
 void importZip(Uri u)throws Exception{File temp=new File(getCacheDir(),"import");del(temp);temp.mkdirs();try(ZipInputStream z=new ZipInputStream(getContentResolver().openInputStream(u))){ZipEntry e;while((e=z.getNextEntry())!=null){File out=new File(temp,e.getName());String base=temp.getCanonicalPath()+File.separator;if(!out.getCanonicalPath().startsWith(base))throw new IOException("Archivio non valido");if(e.isDirectory()){out.mkdirs();z.closeEntry();continue;}File parent=out.getParentFile();if(parent!=null)parent.mkdirs();try(OutputStream os=new FileOutputStream(out)){copyOpen(z,os);}z.closeEntry();}}File mf=new File(temp,"manifest.json");if(!mf.exists())throw new IOException("manifest.json non trovato");JSONObject m=new JSONObject(read(mf));JSONArray a=m.getJSONArray("items");SharedPreferences.Editor ed=pref.edit().clear().putInt("count",Math.max(MIN,a.length()));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);ed.putString("n"+i,o.optString("name",""));String t=o.optString("thumb","");if(!t.isEmpty()){File dst=image(i,true);copyAndClose(new FileInputStream(new File(temp,t)),dst);ed.putString("t"+i,dst.getAbsolutePath());}String c=o.optString("code","");if(!c.isEmpty()){File dst=image(i,false);copyAndClose(new FileInputStream(new File(temp,c)),dst);ed.putString("c"+i,dst.getAbsolutePath());}}ed.apply();del(temp);}
 String read(File f)throws IOException{ByteArrayOutputStream o=new ByteArrayOutputStream();try(InputStream in=new FileInputStream(f)){copyOpen(in,o);}return o.toString("UTF-8");}void del(File f){if(!f.exists())return;if(f.isDirectory()){File[]a=f.listFiles();if(a!=null)for(File x:a)del(x);}f.delete();}
 void info(){label=null;shell("INFORMAZIONI");root.addView(text("Archivio locale per i QR-CODE o Codici a Barre.\n\nLe immagini restano in locale sul dispositivo e l'app funziona offline.\n\nver. 1.5\n\nAutore Christian Marongiu + GPT-5.6 sol think.",17,Color.rgb(17,24,39),Gravity.CENTER),new LinearLayout.LayoutParams(-1,0,1));}public void onBackPressed(){saveLabel();home();}
}
